        "during_switch": "tail",
        "early_finish_free": true,
        "processes": [
          {"id": "A", "arrival": 0, "burst": 7},
          {"id": "B", "arrival": 2, "burst": 4},
          {"id": "C", "arrival": 4, "burst": 6},
